/**
 * PG-canonical text artifacts (Migration 035, Phase 2).
 *
 * Reads/writes for free-form text files keyed (harness_slug, rel_path).
 * The on-disk files at `<harness_dir>/.papercusp/<rel_path>` are written
 * as best-effort mirrors on each save so tools running INSIDE the
 * harness process (orchestrator, workers, plugin scripts) see the same
 * content. PG remains canonical.
 *
 * The orchestrator's role-prompt + snapshot-state read these files
 * directly: supervisor-notes.md, issues.md, memory/*.md, prompts/*.md,
 * etc. If a write only lands in PG and never on disk, the operator UI
 * reads it via loadTextArtifact but the orchestrator/worker is blind
 * to it (verified at round 18: PG=146986b vs file=148628b drift on
 * sheets/issues.md after operator-side edits).
 *
 * Path normalization: PG keys are relative-to-harness-dir (no leading
 * `.papercusp/`). Some callers pass paths with `.papercusp/` prefix (e.g. the
 * memory-file UI uses MEMORY_MAP entries that include the prefix); those
 * get stripped here so reads/writes always hit the same row. Disk path
 * always restores `<harness_dir>/.papercusp/<key>`.
 */
import { mkdir, writeFile } from 'node:fs/promises';
import { createHash } from 'node:crypto';
import { dirname, join } from 'node:path';
import { getOrgPg, generated, typedSql } from '@papercusp/db-org';
import { and, eq, or, sql } from 'drizzle-orm';

const t = generated.harnessTextArtifactsInHarnessShared;
import { loadHarnessRegistry } from './harness-registry';
import { notifySyncInvalidate } from './sync-sse';
import { activeWorkspaceId } from './workspace-registry';

/**
 * workspace_id stamp for operator-side writes (EI-280): this lib runs on the
 * admin handle (RLS-bypass), so without an explicit stamp every insert minted
 * a blank-workspace row — invisible to the RLS-scoped artifacts:* agent tools
 * and a poison pill for their upserts. Stamp the operator's active workspace;
 * on conflict, adopt a blank-stamped legacy row (never re-home a properly
 * stamped one).
 */
const adoptBlankWorkspace = sql`CASE WHEN ${t.workspaceId} = '' THEN EXCLUDED.workspace_id ELSE ${t.workspaceId} END`;

function normalizeRelPath(rel: string): string {
  // Drop leading `.papercusp/` so the PG key is consistent with the bare
  // relative-to-harness-dir convention.
  return rel.replace(/^\.papercusp\//, '');
}

/** Content-addressed snapshots share the canonical artifact table, not its mirrors.
 * Ordinary artifact mutations cannot replace, append to or delete these revisions.
 * Raw DB/admin compromise is outside this API guarantee; reads verify bytes anew.
 */
const IMMUTABLE_PREFIX = 'immutable/sha256/';
function assertMutableKey(key: string): void {
  if (key.startsWith('immutable/')) throw new Error('text_artifact_immutable_namespace');
}
function immutableKey(sha256: string): string {
  if (!/^[a-f0-9]{64}$/.test(sha256)) throw new Error('text_artifact_invalid_digest');
  return `${IMMUTABLE_PREFIX}${sha256}.json`;
}
const contentSha256 = (content: string) => createHash('sha256').update(content).digest('hex');

export async function loadImmutableTextArtifact(slug: string, sha256: string): Promise<string | null> {
  const { db } = getOrgPg();
  const rows = await db.select({ content: t.content }).from(t).where(and(
    eq(t.harnessSlug, slug), eq(t.relPath, immutableKey(sha256)), eq(t.workspaceId, activeWorkspaceId()),
  )).limit(1);
  const content = rows[0]?.content ?? null;
  if (content !== null && contentSha256(content) !== sha256) throw new Error('text_artifact_immutable_corrupt');
  return content;
}

/** Idempotent concurrent insert; a collision/foreign scope never overwrites a row. */
export async function saveImmutableTextArtifact(slug: string, content: string): Promise<{ sha256: string; relPath: string }> {
  const sha256 = contentSha256(content), relPath = immutableKey(sha256);
  const { db } = getOrgPg();
  await db.insert(t).values({ harnessSlug: slug, relPath, content,
    updatedAt: Date.now(), workspaceId: activeWorkspaceId() }).onConflictDoNothing();
  if (await loadImmutableTextArtifact(slug, sha256) !== content) throw new Error('text_artifact_immutable_conflict');
  return { sha256, relPath };
}

/** Permanent first-writer slots in the SAME canonical store. Used for execution
 * consumption, where content addressing alone cannot exclude a second start.
 * A crash after claiming deliberately leaves an uncertain/consumed execution;
 * callers must inspect it, never silently retry a potentially effected run.
 */
function immutableClaimKey(slot: string): string {
  if (!slot.trim()) throw new Error('text_artifact_empty_claim');
  return `immutable/claims/${contentSha256(slot)}.json`;
}
export async function loadImmutableTextArtifactClaim(slug: string, slot: string): Promise<string | null> {
  const { db } = getOrgPg();
  const rows = await db.select({ content: t.content }).from(t).where(and(
    eq(t.harnessSlug, slug), eq(t.relPath, immutableClaimKey(slot)), eq(t.workspaceId, activeWorkspaceId()),
  )).limit(1);
  if (!rows.length) return null;
  const value = JSON.parse(rows[0].content) as { sha256: string; content: string };
  if (typeof value.content !== 'string' || contentSha256(value.content) !== value.sha256) {
    throw new Error('text_artifact_immutable_corrupt');
  }
  return value.content;
}
export async function claimImmutableTextArtifact(slug: string, slot: string, content: string): Promise<boolean> {
  const { db } = getOrgPg();
  const rows = await db.insert(t).values({ harnessSlug: slug, relPath: immutableClaimKey(slot),
    content: JSON.stringify({ sha256: contentSha256(content), content }),
    updatedAt: Date.now(), workspaceId: activeWorkspaceId(),
  }).onConflictDoNothing().returning({ relPath: t.relPath });
  if (await loadImmutableTextArtifactClaim(slug, slot) !== content) throw new Error('text_artifact_immutable_claim_conflict');
  return rows.length === 1;
}

async function notifyTextArtifactChange(slug: string, _key: string): Promise<void> {
  // Generic invalidation — clients subscribed to harnessTextArtifact.byHarness
  // refetch. The query returns all rows for the slug, so per-relPath args
  // would be ignored. (Renamed from byHarnessAndPath in the eager-fetch arc.)
  await notifySyncInvalidate('harnessTextArtifact.byHarness', {
    harnessSlug: slug,
  });
}

/** Resolve `<harness_dir>/.papercusp/<rel_path>` for the given slug. Returns
 *  null when the harness isn't in the registry (operator-side write to a
 *  not-yet-registered harness — ignore the disk mirror in that case). */
async function diskPathFor(slug: string, key: string): Promise<string | null> {
  const reg = await loadHarnessRegistry();
  const project = reg.projects.find((p) => p.slug === slug);
  if (!project) return null;
  return join(project.path, '.papercusp', key);
}

/** Best-effort mirror to disk. PG row is canonical; disk is for the
 *  orchestrator/worker process to read via `<harness_dir>/.papercusp/<rel>`. */
async function mirrorToDisk(slug: string, key: string, content: string): Promise<void> {
  try {
    const path = await diskPathFor(slug, key);
    if (!path) return;
    await mkdir(dirname(path), { recursive: true });
    await writeFile(path, content, 'utf8');
  } catch {
    /* file write failed — PG already won; orchestrator will see stale on
     *  disk until next write. Acceptable for V1; the alternative (failing
     *  the PG write) trades a worse failure mode (silent UI loss). */
  }
}

export async function loadTextArtifact(slug: string, relPath: string): Promise<string | null> {
  const key = normalizeRelPath(relPath);
  const { db } = getOrgPg();
  const rows = await db
    .select({ content: t.content })
    .from(t)
    .where(and(eq(t.harnessSlug, slug), eq(t.relPath, key)))
    .limit(1);
  return rows[0]?.content ?? null;
}

export interface SaveTextArtifactOpts {
  /** Override the disk mirror path. Default: `<project.path>/.papercusp/<rel_path>`.
   *  Use for files whose canonical disk location is NOT under .papercusp/ —
   *  e.g. .mcp.json at project root, .claude/settings.json. The PG row is
   *  always keyed by the rel_path passed in, regardless of disk location. */
  customDiskPath?: string;
}

export async function saveTextArtifact(slug: string, relPath: string, content: string, opts: SaveTextArtifactOpts = {}): Promise<void> {
  const key = normalizeRelPath(relPath);
  assertMutableKey(key);
  const { db } = getOrgPg();
  const now = Date.now();
  await db
    .insert(t)
    .values({ harnessSlug: slug, relPath: key, content, updatedAt: now, workspaceId: activeWorkspaceId() })
    .onConflictDoUpdate({
      target: [t.harnessSlug, t.relPath],
      set: {
        content: sql`EXCLUDED.content`,
        updatedAt: sql`EXCLUDED.updated_at`,
        workspaceId: adoptBlankWorkspace,
      },
    });
  if (opts.customDiskPath) {
    try {
      await mkdir(dirname(opts.customDiskPath), { recursive: true });
      await writeFile(opts.customDiskPath, content, 'utf8');
    } catch { /* mirror best-effort */ }
  } else {
    await mirrorToDisk(slug, key, content);
  }
  await notifyTextArtifactChange(slug, key);
}

/** Conditional writes reuse the canonical artifact row; null means create-only.
 * Callers must read PG, never the best-effort disk mirror, before comparing.
 */
export async function compareAndSwapTextArtifact(slug: string, relPath: string,
  expectedContent: string | null, content: string): Promise<boolean> {
  const key = normalizeRelPath(relPath), workspaceId = activeWorkspaceId();
  assertMutableKey(key);
  const { db } = getOrgPg();
  const values = { content, updatedAt: Date.now(), workspaceId };
  const rows = expectedContent === null
    ? await db.insert(t).values({ harnessSlug: slug, relPath: key, ...values })
      .onConflictDoNothing().returning({ content: t.content })
    : await db.update(t).set(values).where(and(eq(t.harnessSlug, slug), eq(t.relPath, key),
      eq(t.content, expectedContent), or(eq(t.workspaceId, workspaceId), eq(t.workspaceId, ''))))
      .returning({ content: t.content });
  if (!rows.length) return false;
  await mirrorToDisk(slug, key, content);
  await notifyTextArtifactChange(slug, key);
  return true;
}

export async function appendTextArtifact(slug: string, relPath: string, suffix: string): Promise<void> {
  const key = normalizeRelPath(relPath);
  assertMutableKey(key);
  const { db } = getOrgPg();
  const now = Date.now();
  // PG-side `||` concat keeps the append atomic. Drizzle's `set` accepts
  // raw sql snippets for cases the query-builder can't express cleanly.
  // RETURNING comes back typed via .returning({ content }).
  const rows = await db
    .insert(t)
    .values({ harnessSlug: slug, relPath: key, content: suffix, updatedAt: now, workspaceId: activeWorkspaceId() })
    .onConflictDoUpdate({
      target: [t.harnessSlug, t.relPath],
      set: {
        content: sql`${t.content} || EXCLUDED.content`,
        updatedAt: sql`EXCLUDED.updated_at`,
        workspaceId: adoptBlankWorkspace,
      },
    })
    .returning({ content: t.content });
  const merged = rows[0]?.content ?? suffix;
  await mirrorToDisk(slug, key, merged);
  await notifyTextArtifactChange(slug, key);
}

export async function deleteTextArtifact(slug: string, relPath: string): Promise<void> {
  const key = normalizeRelPath(relPath);
  assertMutableKey(key);
  const { db } = getOrgPg();
  await db.delete(t).where(and(eq(t.harnessSlug, slug), eq(t.relPath, key)));
  // Don't unlink the file — the harness contract may have a different
  // process (orchestrator, harness-CLI) treating the file as primary. A
  // PG delete from the operator UI just stops mirroring; the file stays
  // until something else removes it.
  await notifyTextArtifactChange(slug, key);
}

/**
 * artifacts:save — upsert one OR many PG-canonical text artifacts.
 *
 * Replaces the entire `content` for (harness_slug, rel_path). PG is
 * canonical (per the "PG-canonical, no FS mirrors" project rule); no
 * disk write happens here. If a consumer needs the content on disk
 * (orchestrator prompt assembly, harness-CLI), it should read from PG
 * via `artifacts:load` rather than tail a file.
 *
 * Bulk by default (the house keyed-array contract,
 * bulk-endpoint-standardization-2026-06-21): the artifact key is the COMPOUND
 * `(slug, rel_path)` (slug defaults to the spawn ctx's harness), and `content`
 * rides per item. Pass a single `{ slug?, rel_path, content }` for n=1, or
 * `items:[{ slug?, rel_path, content }]` for many → { ok, results:[{ ok, slug,
 * rel_path, bytes, updated_at | error }], counts }. Each result self-describes
 * its (slug, rel_path); a missing-slug / invalid-slug item fails only itself.
 */

import { z } from 'zod';
import { defineTool } from '@papercusp/tooldef';
import { SLUG_RE, slugRequires, resolveSlug } from './_slug-requires';
import { SU_WRITE_ROLES } from '../../role-config';
// The bulk helpers' LEAF module — relative, NOT the '@papercusp/agent-mcp'
// barrel (see artifacts/load.ts for why: ESM circular-init + node-moduleResolution).
import { runBulk, bulkContent } from '../../_bulk';
// NB: 'tester' is not an AGENT_ROLES member and never was — the phantom
// entry gated nothing (audit P-047).

function normalizeRelPath(rel: string): string {
  return rel.replace(/^\.papercusp\//, '');
}

const SaveItem = z.object({
  slug: z.string().min(1).regex(SLUG_RE).optional(),
  rel_path: z.string().min(1),
  content: z.string(),
});
type SaveItem = z.infer<typeof SaveItem>;

export default defineTool({
  name: 'artifacts:save',
  needsWorkspaceTx: true,
  description:
    'Upsert one OR many PG-canonical text artifacts (harness_text_artifacts) by (harness_slug, rel_path); replaces existing content. Pass a single `{ slug?, rel_path, content }` or `items:[{ slug?, rel_path, content }]` for several. Returns { ok, results:[{ ok, slug, rel_path, bytes, updated_at | error }], counts } — correlate by (slug, rel_path), not by position; a missing / invalid-slug item fails only itself.',
  capability: 'artifacts:write',
  guidance: {
    when: 'Persist a generated text artifact for later reads by other agents or future turns. Replaces existing content at the same (harness_slug, rel_path). Save several at once via `items`.',
    notWhen: 'For appending to an existing file, use `artifacts:append` — save fully replaces. For source code, write to the repo via filesystem tools, not artifacts.',
    chaining: 'Bulk: single { slug?, rel_path, content } | items[] → { ok, results, counts }; correlate by (slug, rel_path) not position; one failure never fails the rest.',
  },
  requirePrincipal: false,
  agentRoles: [...SU_WRITE_ROLES],
  rolesQuota: {
    worker: { perChunk: 20 },
    architect: { perRun: 50 },
    scoper: { perRun: 50 },
    operator: { perRun: 200 },
  },
  args: z
    .object({
      slug: z.string().min(1).regex(SLUG_RE).optional(),
      rel_path: z.string().min(1).optional(),
      content: z.string().optional(),
      items: z.array(SaveItem).min(1).max(100).optional().describe('artifacts to upsert (1–100), each { slug?, rel_path, content }'),
    })
    .refine((a) => Boolean(a.items?.length) || (Boolean(a.rel_path) && a.content !== undefined), {
      message: 'pass `{ rel_path, content }` (one) or `items:[{ rel_path, content }]` (many)',
    }),
  // Declarative preconditions (adopt-event-rules-engines requires:-half):
  // the former in-handler slug guards, lifted — see ./_slug-requires. The bulk
  // (`items`) path re-asserts per-item slug presence/validity in the handler.
  requires: slugRequires('artifacts:save'),
  async handler(args, ctx) {
    const items: SaveItem[] = args.items?.length
      ? args.items
      : [{ slug: args.slug, rel_path: args.rel_path!, content: args.content! }];
    const now = Date.now();
    // ctx.tx, NOT getOrgPg() (audit P-012): the host picks the handle —
    // workspace-scoped (harness_app + app.workspace_id GUC, RLS-enforced)
    // for normal dispatch, admin only for superuser/cross-workspace
    // dispatch. The admin handle here bypassed harness_text_artifacts'
    // workspace-isolation policy. workspace_id stamps GUC-first, then
    // ctx.workspaceId — the admin path has no GUC, and a bare
    // COALESCE(...,'') there minted the blank legacy rows EI-280 had to
    // repair ('*' = no concrete workspace, never a stamp). The conflict
    // arm ADOPTS a blank-stamped legacy row instead of tripping the
    // policy on it.
    const wsFallback = ctx.workspaceId && ctx.workspaceId !== '*' ? ctx.workspaceId : '';
    const env = await runBulk(
      items,
      async (item) => {
        const r = resolveSlug('artifacts:save', item.slug, ctx.harnessSlug);
        const key = normalizeRelPath(item.rel_path);
        if ('error' in r) {
          return { ok: false as const, slug: item.slug ?? null, rel_path: key, error: r.error };
        }
        const { slug } = r;
        await ctx.tx`
          INSERT INTO harness_shared.harness_text_artifacts (harness_slug, rel_path, content, updated_at, workspace_id)
          VALUES (${slug}, ${key}, ${item.content}, ${now},
                  COALESCE(NULLIF(current_setting('app.workspace_id', true), ''), ${wsFallback}))
          ON CONFLICT (harness_slug, rel_path) DO UPDATE SET
            content      = EXCLUDED.content,
            updated_at   = EXCLUDED.updated_at,
            workspace_id = CASE WHEN harness_text_artifacts.workspace_id = ''
                                THEN EXCLUDED.workspace_id
                                ELSE harness_text_artifacts.workspace_id END
        `;
        return { ok: true as const, slug, rel_path: key, bytes: Buffer.byteLength(item.content, 'utf8'), updated_at: now };
      },
      { keyOf: (item) => ({ slug: item.slug ?? null, rel_path: normalizeRelPath(item.rel_path) }) },
    );
    return bulkContent(env);
  },
});

/**
 * artifacts:load — read one OR many PG-canonical text artifacts for a harness.
 *
 * Same store as `apps/operator/lib/text-artifacts.ts` (Migration 035):
 * `harness_shared.harness_text_artifacts`, keyed (harness_slug, rel_path).
 * Used for memory/*.md, supervisor-notes.md, issues.md, and other free-
 * form per-harness text. Role-gated; agents may read across harnesses
 * by passing an explicit `slug`.
 *
 * The `rel_path` may be passed with or without a leading `.papercusp/`;
 * it's normalised to the bare relative-to-harness-dir form for lookup.
 *
 * Bulk by default (the house keyed-array contract,
 * bulk-endpoint-standardization-2026-06-21): the artifact key is the COMPOUND
 * `(slug, rel_path)` (slug defaults to the spawn ctx's harness). Pass a single
 * `{ slug?, rel_path }` for n=1, or `items:[{ slug?, rel_path }]` for many →
 * { ok, results:[{ ok, slug, rel_path, found, content, updated_at | error }],
 * counts }. Each result self-describes its (slug, rel_path); a missing-slug /
 * invalid-slug item fails only itself.
 */

import { z } from 'zod';
import { defineTool } from '@papercusp/tooldef';
import type { PapercuspUnifiedToolContext } from '@papercusp/operator-core/lib/agent-tools/_tool-context';
import { SLUG_RE, slugRequires, resolveSlug } from './_slug-requires';
import { SU_ROLES } from '../../role-config';
// The bulk helpers' LEAF module — relative, NOT the '@papercusp/agent-mcp'
// barrel: the barrel re-exports through index.ts, an ESM circular-init that
// leaves runBulk/bulkContent undefined at runtime, AND the package-subpath
// self-reference fails the production build's `node` moduleResolution. The
// relative leaf resolves under both and dodges the cycle.
import { runBulk, bulkContent } from '../../_bulk';

// NB: 'tester' is not an AGENT_ROLES member and never was — the phantom
// entry gated nothing (audit P-047).

function normalizeRelPath(rel: string): string {
  return rel.replace(/^\.papercusp\//, '');
}

const LoadItem = z.object({
  slug: z.string().min(1).regex(SLUG_RE).optional(),
  rel_path: z.string().min(1),
});
type LoadItem = z.infer<typeof LoadItem>;

export default defineTool({
  name: 'artifacts:load',
  needsWorkspaceTx: true,
  description:
    'Read one OR many PG-canonical text artifacts (harness_text_artifacts) by (harness_slug, rel_path). Pass a single `{ slug?, rel_path }` or `items:[{ slug?, rel_path }]` for several. Returns { ok, results:[{ ok, slug, rel_path, found, content, updated_at | error }], counts } — correlate by (slug, rel_path), not by position; a missing / invalid-slug item fails only itself. LARGE artifact? Paginate: `offset` + `max_chars` slice each result\'s content (echoed back as content_total_chars / content_offset / content_truncated); ~4000-char pages ride under the model-facing result door, so a series of paged reads beats one clipped blob plus scratch-cursor paging.',
  capability: 'artifacts:read',
  guidance: {
    when: 'You need to read a file the harness wrote earlier (notes, intermediate outputs, plans) by its harness_slug + rel_path. Pass every (slug, rel_path) at once via `items`.',
    notWhen: 'For SOURCE CODE in the user\'s repo, use the filesystem tools / gitnexus. Artifacts are harness-scoped PG-canonical text only.',
    chaining: 'Pair with `artifacts:save` to round-trip, `artifacts:append` to add to an existing one. Bulk: single { slug?, rel_path } | items[] → { ok, results, counts }; correlate by (slug, rel_path) not position; one failure never fails the rest.',
  },
  requirePrincipal: false,
  // The frozen judge must be able to inspect acceptance evidence it is asked
  // to grade. Keep this grant local to the read-only tool: adding `judge` to
  // SU_ROLES would unintentionally widen every standard SU-tool allowlist.
  agentRoles: [...SU_ROLES, 'judge'],
  args: z
    .object({
      slug: z.string().min(1).regex(SLUG_RE).optional(),
      rel_path: z.string().min(1).optional(),
      items: z.array(LoadItem).min(1).max(100).optional().describe('artifact keys to read (1–100), each { slug?, rel_path }'),
      // EI-21471082146021784: deterministic paging for large artifacts. The
      // model-facing result door bounds every result, so a whole-artifact
      // read of a big body arrives clipped with only an opaque scratch
      // cursor; explicit slices let the caller page the REAL content through
      // this tool instead. Same convention as capability:read's byte pages.
      offset: z.number().int().min(0).optional().describe('char offset into each result\'s content (default 0)'),
      max_chars: z
        .number()
        .int()
        .min(1)
        .max(20_000)
        .optional()
        .describe('slice length per result (default: whole content; ~4000 stays under the result door)'),
    })
    .refine((a) => Boolean(a.items?.length) || Boolean(a.rel_path), {
      message: 'pass `rel_path` (one) or `items:[{ rel_path }]` (many)',
    }),
  // Declarative preconditions (adopt-event-rules-engines requires:-half):
  // the former in-handler slug guards, lifted — see ./_slug-requires. The bulk
  // (`items`) path re-asserts per-item slug presence/validity in the handler.
  requires: slugRequires('artifacts:load'),
  async handler(args, ctx: PapercuspUnifiedToolContext) {
    const tx = ctx.tx!;
    const items: LoadItem[] = args.items?.length ? args.items : [{ slug: args.slug, rel_path: args.rel_path! }];
    const env = await runBulk(
      items,
      async (item) => {
        const r = resolveSlug('artifacts:load', item.slug, ctx.harnessSlug);
        const key = normalizeRelPath(item.rel_path);
        if ('error' in r) {
          return { ok: false as const, slug: item.slug ?? null, rel_path: key, error: r.error };
        }
        const { slug } = r;
        // ctx.tx, NOT getOrgPg() — the workspace-scoped handle keeps reads
        // inside the caller's workspace via RLS (audit P-012, see save.ts).
        const rows = await tx<{ content: string; updated_at: string }[]>`
          SELECT content, updated_at
            FROM harness_shared.harness_text_artifacts
           WHERE harness_slug = ${slug} AND rel_path = ${key}
           LIMIT 1
        `;
        const found = rows.length > 0;
        const full = found ? rows[0].content : null;
        const totalChars = full ? full.length : 0;
        const offset = args.offset ?? 0;
        const slice =
          full !== null && args.max_chars != null
            ? full.slice(offset, Math.min(offset + args.max_chars, totalChars))
            : full;
        const truncated = slice !== null && args.max_chars != null && offset + args.max_chars < totalChars;
        return {
          ok: true as const,
          slug,
          rel_path: key,
          found,
          content: slice,
          updated_at: found ? Number(rows[0].updated_at) : null,
          ...(full !== null && args.max_chars != null
            ? { content_total_chars: totalChars, content_offset: offset, content_truncated: truncated }
            : {}),
        };
      },
      { keyOf: (item) => ({ slug: item.slug ?? null, rel_path: normalizeRelPath(item.rel_path) }) },
    );
    return bulkContent(env);
  },
});

/**
 * artifacts:append — append to one OR many PG-canonical text artifacts.
 *
 * Concatenates `suffix` to the existing `content`. If the row doesn't
 * exist yet, creates it with `suffix` as the initial content. Returns
 * the post-append byte length so callers can detect overflow without a
 * follow-up `load`.
 *
 * Bulk by default (the house keyed-array contract,
 * bulk-endpoint-standardization-2026-06-21): the artifact key is the COMPOUND
 * `(slug, rel_path)` (slug defaults to the spawn ctx's harness), and `suffix`
 * rides per item. Pass a single `{ slug?, rel_path, suffix }` for n=1, or
 * `items:[{ slug?, rel_path, suffix }]` for many → { ok, results:[{ ok, slug,
 * rel_path, appended_bytes, total_bytes, updated_at | error }], counts }. Each
 * result self-describes its (slug, rel_path); a missing-slug / invalid-slug
 * item fails only itself.
 */

import { z } from 'zod';
import { defineTool } from '@papercusp/tooldef';
import type { PapercuspUnifiedToolContext } from '@papercusp/operator-core/lib/agent-tools/_tool-context';
import { SLUG_RE, slugRequires, resolveSlug } from './_slug-requires';
import { SU_WRITE_ROLES } from '../../role-config';
// The bulk helpers' LEAF module — relative, NOT the '@papercusp/agent-mcp'
// barrel (see artifacts/load.ts for why: ESM circular-init + node-moduleResolution).
import { runBulk, bulkContent } from '../../_bulk';

// NB: 'tester' is not an AGENT_ROLES member and never was — the phantom
// entry gated nothing (audit P-047).

function normalizeRelPath(rel: string): string {
  return rel.replace(/^\.papercusp\//, '');
}

const AppendItem = z.object({
  slug: z.string().min(1).regex(SLUG_RE).optional(),
  rel_path: z.string().min(1),
  suffix: z.string().min(1),
});
type AppendItem = z.infer<typeof AppendItem>;

export default defineTool({
  name: 'artifacts:append',
  needsWorkspaceTx: true,
  description:
    'Append to one OR many PG-canonical text artifacts (harness_text_artifacts); creates the row if absent. Pass a single `{ slug?, rel_path, suffix }` or `items:[{ slug?, rel_path, suffix }]` for several. Returns { ok, results:[{ ok, slug, rel_path, appended_bytes, total_bytes, updated_at | error }], counts } — correlate by (slug, rel_path), not by position; a missing / invalid-slug item fails only itself.',
  capability: 'artifacts:write',
  guidance: {
    when: 'Add to an existing artifact without losing prior content — running notes, ongoing log, accumulating findings. Append to several at once via `items`.',
    notWhen: 'For replacing the whole file, use `artifacts:save`. For ephemeral within-turn notes, just hold them in your reply.',
    chaining: 'Bulk: single { slug?, rel_path, suffix } | items[] → { ok, results, counts }; correlate by (slug, rel_path) not position; one failure never fails the rest.',
  },
  requirePrincipal: false,
  agentRoles: [...SU_WRITE_ROLES],
  rolesQuota: {
    worker: { perChunk: 50 },
    architect: { perRun: 200 },
    scoper: { perRun: 200 },
    operator: { perRun: 500 },
  },
  args: z
    .object({
      slug: z.string().min(1).regex(SLUG_RE).optional(),
      rel_path: z.string().min(1).optional(),
      suffix: z.string().min(1).optional(),
      items: z.array(AppendItem).min(1).max(100).optional().describe('artifacts to append to (1–100), each { slug?, rel_path, suffix }'),
    })
    .refine((a) => Boolean(a.items?.length) || (Boolean(a.rel_path) && Boolean(a.suffix)), {
      message: 'pass `{ rel_path, suffix }` (one) or `items:[{ rel_path, suffix }]` (many)',
    }),
  // Declarative preconditions (adopt-event-rules-engines requires:-half):
  // the former in-handler slug guards, lifted — see ./_slug-requires. The bulk
  // (`items`) path re-asserts per-item slug presence/validity in the handler.
  requires: slugRequires('artifacts:append'),
  async handler(args, ctx: PapercuspUnifiedToolContext) {
    const tx = ctx.tx!;
    const items: AppendItem[] = args.items?.length
      ? args.items
      : [{ slug: args.slug, rel_path: args.rel_path!, suffix: args.suffix! }];
    const now = Date.now();
    // ctx.tx, NOT getOrgPg() — RLS-scoped write; workspace_id stamps
    // GUC-first then ctx.workspaceId, and the conflict arm adopts
    // blank-stamped legacy rows (audit P-012 + EI-280, see save.ts).
    const wsFallback = ctx.workspaceId && ctx.workspaceId !== '*' ? ctx.workspaceId : '';
    const env = await runBulk(
      items,
      async (item) => {
        const r = resolveSlug('artifacts:append', item.slug, ctx.harnessSlug);
        const key = normalizeRelPath(item.rel_path);
        if ('error' in r) {
          return { ok: false as const, slug: item.slug ?? null, rel_path: key, error: r.error };
        }
        const { slug } = r;
        const rows = await tx<{ content: string }[]>`
          INSERT INTO harness_shared.harness_text_artifacts (harness_slug, rel_path, content, updated_at, workspace_id)
          VALUES (${slug}, ${key}, ${item.suffix}, ${now},
                  COALESCE(NULLIF(current_setting('app.workspace_id', true), ''), ${wsFallback}))
          ON CONFLICT (harness_slug, rel_path) DO UPDATE SET
            content      = harness_text_artifacts.content || EXCLUDED.content,
            updated_at   = EXCLUDED.updated_at,
            workspace_id = CASE WHEN harness_text_artifacts.workspace_id = ''
                                THEN EXCLUDED.workspace_id
                                ELSE harness_text_artifacts.workspace_id END
          RETURNING content
        `;
        const merged = rows[0]?.content ?? item.suffix;
        return {
          ok: true as const,
          slug,
          rel_path: key,
          appended_bytes: item.suffix.length,
          total_bytes: merged.length,
          updated_at: now,
        };
      },
      { keyOf: (item) => ({ slug: item.slug ?? null, rel_path: normalizeRelPath(item.rel_path) }) },
    );
    return bulkContent(env);
  },
});

/**
 * capability:bash — run a shell command. A THIN wrapper over a real `bash -c`
 * (D-004 — wraps real execution, no reimplementation), routed through the
 * shared endpoint dispatch so policy / capability-envelope / telemetry apply
 * (P-010, `agent-capability-confinement-2026-06-13`). It replicates the native
 * Bash tool's ergonomics: combined output streaming (the `output` event),
 * truncation/overflow-to-file, and durable jobs (`run_in_background`).
 *
 * Ordinary calls start one durable job and stream while waiting. Fast commands
 * return terminal output; a command that exceeds the bounded response window
 * returns that SAME job's `bash_id`/`task_id` without killing or restarting it.
 * `timeout` remains the independent execution deadline. Explicit background
 * mode returns the handles immediately; read
 * incremental output with `capability:bash_output` and stop it with
 * `processes:kill` — the way a 5-minute build is run without holding one
 * blocking request. The task id remains observable through the task ledger if
 * the operator restarts and its in-memory bash-job map is lost.
 *
 * BOTH modes have a deadline; they do NOT share one (WI-6677). The explicit-background
 * default is hours, not the ordinary call's two minutes, because a background job
 * is by definition meant to outlive the call — see the constants in
 * `bash-jobs.ts` for why inheriting the foreground pair was a trap.
 */

