const ENV_NAME_RE = /^[A-Za-z_][A-Za-z0-9_]*$/;
const INTEGRATION_KEY_NAME_RE = /^[A-Z][A-Z0-9_]*$/;
const RESERVED_INTEGRATION_ENV_NAMES = new Set([
